func TestDecodeCommentsInsideMultilineContainers(t *testing.T) {
	input := "arr = [\n  1, # first\n  2,\n  \"#\", # hash is string content\n  \"\"\"###\"\"\"\n]\n"
	got, err := Decode(input)
