func ensureTable(root Object, path []string, decl map[string]bool) (Object, error) {
	obj := root
	for i, p := range path {
		if x, ok := obj[p].(Object); ok {
			obj = x
			continue
		}
		if arr, ok := obj[p].([]any); ok && len(arr) > 0 {
			if x, ok := arr[len(arr)-1].(Object); ok {
				obj = x
				continue
			}
		}
		if obj[p] != nil {
			return nil, fmt.Errorf("table conflict")
		}
		x := Object{}
		obj[p] = x
		obj = x
		_ = i
	}
	name := strings.Join(path, ".")
	if decl[name] && !hasArrayAncestor(root, path) {
		return nil, fmt.Errorf("table redefinition")
	}
	decl[name] = true
	return obj, nil
}

func hasArrayAncestor(root Object, path []string) bool {
	obj := root
	for _, part := range path[:len(path)-1] {
		if arr, ok := obj[part].([]any); ok {
			return len(arr) > 0
		}
		x, ok := obj[part].(Object)
		if !ok {
			return false
		}
		obj = x
	}
	return false
}

func parseValue(s string) (any, error) {
