func parseSignedInteger(s string) (int64, error) {
	sign := ""
	if strings.HasPrefix(s, "+") || strings.HasPrefix(s, "-") {
		sign, s = s[:1], s[1:]
	}
	base := 10
	if len(s) > 2 && s[0] == '0' {
		switch s[1] {
		case 'x':
			base, s = 16, s[2:]
		case 'o':
			base, s = 8, s[2:]
		case 'b':
			base, s = 2, s[2:]
		}
	}
	if sign == "-" {
		n, err := strconv.ParseUint(s, base, 64)
		if err != nil || n > 1<<63 {
			return 0, strconv.ErrRange
		}
		if n == 1<<63 {
			return -1 << 63, nil
		}
		return -int64(n), nil
	}
	n, err := strconv.ParseUint(s, base, 64)
	if err != nil || n > 1<<63-1 {
		return 0, strconv.ErrRange
	}
	return int64(n), nil
}

